import {WIDTH as W,HEIGHT as H,clamp,collides,waveAt,shotPattern,createGame,applyPickup} from './engine.js';
const $ = id => document.getElementById(id);
const canvas=$('game'),ctx=canvas.getContext('2d');
const ui={score:$('score'),best:$('best'),wave:$('wave'),lives:$('lives'),weapon:$('weapon'),dots:$('weapon-dots'),status:$('flight-status'),overlay:$('overlay'),title:$('overlay-title'),text:$('overlay-text'),eyebrow:$('overlay-eyebrow'),start:$('start'),pause:$('pause'),sound:$('sound'),toast:$('toast')};
let g=createGame(),state='ready',last=0,best=0,soundOn=false,audio=null,pointer=null,toastTime=0,frameTime=0;
const keys=new Set(),stars=Array.from({length:95},()=>({x:Math.random()*W,y:Math.random()*H,size:Math.random()*1.6+.4,speed:Math.random()*35+14}));
try { best=Number(localStorage.getItem('sky-strike-best'))||0; }catch{}
ui.best.textContent=String(best).padStart(6,'0');
function tone(freq,duration=.08,type='sine',volume=.035,end=freq){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),v=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(10,end),audio.currentTime+duration);v.gain.setValueAtTime(volume,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('visible');toastTime=2;}
function updateHud(){ui.score.textContent=String(g.score).padStart(6,'0');ui.wave.textContent=String(g.wave).padStart(2,'0');ui.lives.textContent=Array.from({length:3},(_,i)=>i<g.player.lives?'◆':'◇').join(' ');ui.lives.setAttribute('aria-label',`${g.player.lives} 条生命`);ui.weapon.textContent=['单发机炮','双联机炮','三向弹幕'][g.player.level-1];ui.dots.textContent=['● ○ ○','● ● ○','● ● ●'][g.player.level-1];}
function start(){g=createGame();state='playing';keys.clear();pointer=null;ui.overlay.classList.add('hidden');ui.pause.disabled=false;ui.pause.textContent='暂停 Ⅱ';ui.pause.setAttribute('aria-label','暂停游戏');ui.status.textContent='自动开火中';updateHud();notify('WAVE 01 · 起飞');canvas.focus({preventScroll:true});tone(330,.25,'triangle',.07,660);}
function pause(){if(state==='playing'){state='paused';keys.clear();pointer=null;ui.overlay.classList.remove('hidden');ui.eyebrow.textContent='FLIGHT PAUSED';ui.title.innerHTML='稍作<span>休整</span>';ui.text.textContent='准备好后，继续你的飞行';ui.start.innerHTML='继续飞行 <span>RESUME</span>';ui.pause.textContent='继续 ▶';ui.pause.setAttribute('aria-label','继续游戏');ui.status.textContent='已暂停';}else if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');ui.pause.textContent='暂停 Ⅱ';ui.pause.setAttribute('aria-label','暂停游戏');ui.status.textContent='自动开火中';canvas.focus({preventScroll:true});}}
function end(){state='over';pointer=null;keys.clear();ui.pause.disabled=true;const record=g.score>best;if(record){best=g.score;try{localStorage.setItem('sky-strike-best',String(best));}catch{}}ui.best.textContent=String(best).padStart(6,'0');ui.eyebrow.textContent=record?'NEW PERSONAL BEST':'MISSION COMPLETE';ui.title.innerHTML=record?'新的<span>纪录</span>':'飞行<span>结束</span>';ui.text.textContent=`得分 ${g.score.toLocaleString()} · 到达第 ${g.wave} 波\n击落 ${g.kills} 架敌机 · 飞行 ${Math.floor(g.time)} 秒`;ui.start.innerHTML='再次起飞 <span>RETRY</span>';ui.overlay.classList.remove('hidden');ui.status.textContent='飞行结束';tone(250,.45,'triangle',.08,70);}
ui.start.addEventListener('click',()=>state==='paused'?pause():start());ui.pause.addEventListener('click',pause);
ui.sound.addEventListener('click',()=>{soundOn=!soundOn;ui.sound.textContent=`声音 ${soundOn?'开':'关'}`;ui.sound.setAttribute('aria-label',soundOn?'关闭声音':'开启声音');ui.sound.setAttribute('aria-pressed',String(soundOn));if(soundOn)tone(620,.12);});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','p','escape',' '].includes(key)){if(e.target.tagName==='BUTTON'&&key===' ')return;e.preventDefault();if(!e.repeat&&(key==='p'||key==='escape'))pause();else if(!e.repeat&&key===' '&&(state==='ready'||state==='over'))start();else keys.add(key);}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{if(state==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height};}
canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();const p=point(e);pointer={id:e.pointerId,x:p.x,y:p.y};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId||state!=='playing')return;const p=point(e);g.player.x=clamp(g.player.x+p.x-pointer.x,22,W-22);g.player.y=clamp(g.player.y+p.y-pointer.y,35,H-30);pointer.x=p.x;pointer.y=p.y;});
for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,e=>{if(pointer?.id===e.pointerId)pointer=null;});
function burst(x,y,color,count=18){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*155;g.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.3+Math.random()*.4,max:.7,size:1+Math.random()*3,color});}}
function hurt(){if(g.player.invincible>0)return;g.player.lives--;g.player.invincible=2.2;g.shake=.3;burst(g.player.x,g.player.y,'#ffbc6a',24);tone(90,.2,'sawtooth',.07,30);updateHud();if(g.player.lives<=0)end();}
function spawn(){const heavy=g.wave>=3&&Math.random()<.23;const scout=!heavy&&Math.random()<.36;const x=35+Math.random()*(W-70);g.enemies.push({x,y:-45,base:x,phase:Math.random()*6.28,r:heavy?24:scout?13:17,hp:heavy?7+g.wave:scout?1:2+Math.floor(g.wave/3),maxHp:heavy?7+g.wave:scout?1:2+Math.floor(g.wave/3),speed:heavy?48+g.wave*3:scout?125+g.wave*5:68+g.wave*5,kind:heavy?'heavy':scout?'scout':'fighter',fire:1+Math.random()*1.6});}
function tick(dt){g.time+=dt;g.player.invincible=Math.max(0,g.player.invincible-dt);g.shake=Math.max(0,g.shake-dt);const next=waveAt(g.time);if(next!==g.wave){g.wave=next;notify(`WAVE ${String(next).padStart(2,'0')} · 敌机来袭`);tone(400,.18,'triangle',.06,800);updateHud();}let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);const norm=Math.hypot(dx,dy)||1;g.player.x=clamp(g.player.x+dx/norm*300*dt,22,W-22);g.player.y=clamp(g.player.y+dy/norm*300*dt,35,H-30);
g.fire-=dt;if(g.fire<=0){g.fire=.16;for(const shot of shotPattern(g.player.level))g.bullets.push({x:g.player.x+shot.x,y:g.player.y-25,vx:shot.vx,vy:-590,r:4});tone(880,.04,'triangle',.018,440);}
g.spawn-=dt;if(g.spawn<=0){g.spawn=Math.max(.25,1.1-g.wave*.065)*(Math.random()*.45+.75);spawn();}
for(const b of g.bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;}for(const b of g.enemyBullets){b.x+=b.vx*dt;b.y+=b.vy*dt;}
for(const e of g.enemies){e.y+=e.speed*dt;e.phase+=dt*1.5;e.x=clamp(e.base+Math.sin(e.phase)*(e.kind==='scout'?40:18),24,W-24);e.fire-=dt;if(e.fire<=0&&e.y>20&&e.y<g.player.y-70){e.fire=Math.max(.6,2.5-g.wave*.08);const angle=Math.atan2(g.player.y-e.y,g.player.x-e.x),speed=115+Math.min(110,g.wave*9);for(const spread of e.kind==='heavy'?[-.23,0,.23]:[0])g.enemyBullets.push({x:e.x,y:e.y+15,vx:Math.cos(angle+spread)*speed,vy:Math.sin(angle+spread)*speed,r:5});}if(collides(e,g.player)){e.dead=true;burst(e.x,e.y,'#ffa15a');hurt();if(state!=='playing')return;}}
for(const b of g.bullets){if(b.dead)continue;for(const e of g.enemies){if(e.dead)continue;if(collides(b,e)){b.dead=true;e.hp--;burst(b.x,b.y,'#82f1ff',3);if(e.hp<=0){e.dead=true;g.kills++;g.score+=e.kind==='heavy'?300:e.kind==='scout'?60:100;burst(e.x,e.y,e.kind==='heavy'?'#ffa86d':'#ffc474',e.kind==='heavy'?30:18);tone(e.kind==='heavy'?80:130,.13,'sawtooth',.035,35);if(g.kills%8===0)g.pickups.push({x:e.x,y:e.y,r:15,type:'power'});else if(g.kills%13===0)g.pickups.push({x:e.x,y:e.y,r:15,type:'health'});updateHud();}break;}}}
for(const b of g.enemyBullets)if(!b.dead&&collides(b,g.player)){b.dead=true;hurt();if(state!=='playing')return;}
for(const p of g.pickups){p.y+=80*dt;if(collides({...p,r:23},g.player)){p.dead=true;const max=p.type==='power'?g.player.level===3:g.player.lives===3;applyPickup(g.player,p.type);if(max)g.score+=150;notify(max?'补给奖励 +150':p.type==='power'?'火力升级':'装甲修复');tone(500,.2,'sine',.08,1000);updateHud();}}
g.bullets=g.bullets.filter(b=>!b.dead&&b.y>-25&&b.x>-10&&b.x<W+10);g.enemies=g.enemies.filter(e=>!e.dead&&e.y<H+60);g.enemyBullets=g.enemyBullets.filter(b=>!b.dead&&b.y<H+20&&b.y>-30&&b.x>-20&&b.x<W+20);g.pickups=g.pickups.filter(p=>!p.dead&&p.y<H+20);}
function polygon(points,fill,stroke){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function aircraft(x,y,kind='player',scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);if(kind==='player'){ctx.shadowColor='#53dfff';ctx.shadowBlur=14;polygon([[-6,22],[0,39+Math.sin(frameTime*35)*8],[6,22]],'#5ce3ff');ctx.shadowBlur=0;polygon([[0,-30],[7,-9],[27,14],[26,23],[7,15],[7,27],[0,23],[-7,27],[-7,15],[-26,23],[-27,14],[-7,-9]],'#a8c9dd','#d8f9ff');polygon([[0,-27],[5,11],[0,21],[-5,11]],'#61daf1');polygon([[0,-15],[4,0],[0,5],[-4,0]],'#0b304d');polygon([[-21,14],[-10,7],[-10,13],[-21,20]],'#26798f');polygon([[21,14],[10,7],[10,13],[21,20]],'#26798f');}else{const heavy=kind==='heavy';ctx.scale(heavy?1.4:kind==='scout'?.8:1,heavy?1.3:1);polygon([[0,24],[7,5],[22,-8],[22,-19],[7,-12],[4,-25],[-4,-25],[-7,-12],[-22,-19],[-22,-8],[-7,5]],heavy?'#ab6d72':'#ad879b',heavy?'#ffd4a1':'#efb8be');polygon([[0,19],[5,-7],[0,-15],[-5,-7]],'#622e49');ctx.fillStyle='#ffd090';ctx.fillRect(-3,-9,6,10);}ctx.restore();}
function draw(){ctx.save();ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#102942');bg.addColorStop(.5,'#0b1c32');bg.addColorStop(1,'#122238');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#7daacd09';ctx.lineWidth=1;const scroll=(frameTime*17)%60;for(let y=-60;y<H+60;y+=60){ctx.beginPath();ctx.moveTo(0,y+scroll);ctx.lineTo(W,y+scroll);ctx.stroke();}for(let x=0;x<W;x+=60){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(const s of stars){ctx.fillStyle=`rgba(167,214,239,${s.size*.23})`;ctx.fillRect(s.x,(s.y+frameTime*s.speed)%H,s.size,s.size*2.5);}if(g.shake>0)ctx.translate((Math.random()-.5)*8,(Math.random()-.5)*8);
if(state==='ready'){ctx.globalAlpha=.14;aircraft(105,170,'fighter',1.2);aircraft(390,110,'fighter');aircraft(245,95,'heavy');ctx.globalAlpha=1;aircraft(240,580,'player',1.3);}else{for(const p of g.pickups){ctx.save();ctx.translate(p.x,p.y);ctx.shadowColor=p.type==='power'?'#63e7ff':'#c0f299';ctx.shadowBlur=16;ctx.fillStyle='#15394a';ctx.strokeStyle=ctx.shadowColor;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-13,-13,26,26,5);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=ctx.strokeStyle;ctx.font='bold 23px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(p.type==='power'?'↑':'+',0,0);ctx.restore();}for(const b of g.bullets){ctx.shadowColor='#63f6ff';ctx.shadowBlur=10;ctx.fillStyle='#b1fbff';ctx.fillRect(b.x-2,b.y-9,4,17);}ctx.shadowBlur=0;for(const e of g.enemies){aircraft(e.x,e.y,e.kind);if(e.kind==='heavy'){ctx.fillStyle='#4e3c4c';ctx.fillRect(e.x-22,e.y-39,44,3);ctx.fillStyle='#eaaa77';ctx.fillRect(e.x-22,e.y-39,44*e.hp/e.maxHp,3);}}for(const b of g.enemyBullets){ctx.shadowColor='#ff955d';ctx.shadowBlur=10;ctx.fillStyle='#ffaf73';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffe7bf';ctx.beginPath();ctx.arc(b.x,b.y,2,0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;if(g.player.lives>0){ctx.globalAlpha=g.player.invincible>0?(Math.sin(frameTime*25)>.1?.4:1):1;aircraft(g.player.x,g.player.y);ctx.globalAlpha=1;if(g.player.invincible>0){ctx.strokeStyle='#65d9fa55';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(g.player.x,g.player.y,35,0,Math.PI*2);ctx.stroke();}}}
for(const p of g.particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;ctx.restore();}
function frame(time){const dt=Math.min((time-last)/1000||0,1/30);last=time;if(state!=='paused'){frameTime+=dt;if(state==='playing')tick(dt);for(const p of g.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;}g.particles=g.particles.filter(p=>p.life>0);if(toastTime>0){toastTime-=dt;if(toastTime<=0)ui.toast.classList.remove('visible');}}draw();requestAnimationFrame(frame);}
updateHud();requestAnimationFrame(frame);
